package com.kongye.floatball;
import android.app.Activity;
import android.graphics.*;
import android.view.*;
import android.view.inputmethod.*;
import android.webkit.WebView;
final class V20Checks {
    private static int count;private static void check(boolean value,String label){count++;if(!value)throw new AssertionError(label);}
    static void run(Activity c){count=0;String error="";Bitmap source=Bitmap.createBitmap(120,80,Bitmap.Config.ARGB_8888);ImageEditView view=new ImageEditView(c,source);try{
        view.measure(View.MeasureSpec.makeMeasureSpec(480,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY));view.layout(0,0,480,320);view.color(Color.WHITE);view.tool("text");view.text(20,40,"KY");view.text(70,65,"Q");EditorChecks.touch(view,MotionEvent.ACTION_DOWN,90,140);EditorChecks.touch(view,MotionEvent.ACTION_UP,90,140);view.textColor(Color.RED);org.json.JSONArray marks=new org.json.JSONArray(view.watermark());check(marks.getJSONObject(0).getInt("color")==Color.RED,"palette updates selected existing text");check(marks.getJSONObject(1).getInt("color")==Color.WHITE,"palette leaves other labels unchanged");check(marks.getJSONObject(0).getString("text").equals("KY"),"color switch keeps text");Bitmap flat=view.render();check(EditorChecks.red(flat)>0,"selected color reaches actual pixels");flat.recycle();
        view.reset();view.tool("text");EditorChecks.touch(view,0,80,160);EditorChecks.touch(view,1,80,160);InputConnection input=view.onCreateInputConnection(new EditorInfo());input.commitText("1234",1);view.textColor(Color.YELLOW);marks=new org.json.JSONArray(view.watermark());check(marks.getJSONObject(0).getInt("color")==Color.YELLOW,"palette updates live input label");check(marks.getJSONObject(0).getString("text").equals("1234"),"live label keeps committed characters");view.reset();check(view.watermark().isEmpty(),"no-operation watermark remains empty");
        view.tool("text");EditorChecks.touch(view,0,80,160);EditorChecks.touch(view,1,80,160);final boolean[] done={false};view.onTextDone(()->done[0]=true);view.onCreateInputConnection(new EditorInfo()).performEditorAction(EditorInfo.IME_ACTION_DONE);check(done[0],"watermark editor can route IME Done to preparation");
        RecordingSpec old=new RecordingSpec();old.screenW=1080;old.screenH=2520;old.density=420;old.crop=new Rect(120,300,840,1500);old.gif=true;old.shortSide=240;old.hide=true;old.watermark="session text";RecordingSetup setup=new RecordingSetup(c,false,()->{},()->{});setup.restore(RecordingSpec.read(old.write(new android.content.Intent())));check(setup.spec.gif&&setup.spec.hide&&setup.spec.shortSide==240,"cancel return keeps mode and options");check(setup.spec.watermark.equals("session text"),"cancel return keeps current session watermark");check(setup.spec.crop.left==Math.round(120*setup.spec.screenW/1080f)&&setup.spec.crop.top==Math.round(300*setup.spec.screenH/2520f),"cancel return maps crop to current display");
    }catch(Throwable t){error=t.getClass().getSimpleName()+": "+t.getMessage();}finally{view.dispose();source.recycle();}Prefs.of(c).edit().putInt("qa_v20_checks",count).putBoolean("qa_v20_pass",error.isEmpty()).putString("qa_v20_error",error).apply();}
    private static WebView browser()throws Exception{java.lang.reflect.Field f=FloatService.class.getDeclaredField("browser");f.setAccessible(true);Object b=f.get(FloatService.instance);java.lang.reflect.Field w=FloatingBrowser.class.getDeclaredField("web");w.setAccessible(true);return (WebView)w.get(b);}
    static void installPage(Activity c){try{browser().loadDataWithBaseURL("https://kongye.invalid/","<!doctype html><meta name='viewport' content='width=device-width,initial-scale=1'><title>KONGYE QA</title><script>window.testCounter=37</script><body style='margin:0;height:5000px;background:linear-gradient(#b8e2d1,#e2edfa)'><h1>KONGYE QA</h1><p>Local browser window state check</p></body>","text/html","UTF-8",null);}catch(Exception e){Prefs.of(c).edit().putString("qa_browser_test_error",e.toString()).apply();}}
    static void inspectPage(Activity c){try{browser().evaluateJavascript("JSON.stringify([window.testCounter,window.scrollY])",value->Prefs.of(c).edit().putString("qa_browser_test_state",value).apply());}catch(Exception e){Prefs.of(c).edit().putString("qa_browser_test_error",e.toString()).apply();}}
    static void scrollPage(){try{browser().evaluateJavascript("window.scrollTo(0,600)",null);}catch(Exception e){throw new RuntimeException(e);}}
}
